-- ===========================================
-- Fichier: 19-10-26.sql
-- Date: 19/10/2026
-- Projet Recrutement - Workflow complet
-- Manager -> RH -> Finance -> Direction -> Candidat
-- Contenu: Schema complet + donnees de reference + comptes de test
-- Compatible PostgreSQL (GENERATED ALWAYS AS IDENTITY)
-- Pour H2: voir src/main/resources/schema-h2.sql (GENERATED BY DEFAULT)
-- ===========================================

CREATE TABLE departement (
    id   INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    nom  VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE role (
    id       INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code     VARCHAR(20) NOT NULL UNIQUE,
    libelle  VARCHAR(50) NOT NULL
);

-- Decision d'un valideur (demande de poste, offre, conditions de travail)
CREATE TABLE decision (
    id       INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code     VARCHAR(20) NOT NULL UNIQUE,
    libelle  VARCHAR(50) NOT NULL
);

CREATE TABLE statut_offre (
    id       INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code     VARCHAR(30) NOT NULL UNIQUE,
    libelle  VARCHAR(80) NOT NULL
);

CREATE TABLE etape_recrutement (
    id       INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code     VARCHAR(20) NOT NULL UNIQUE,
    libelle  VARCHAR(50) NOT NULL,
    ordre    INT NOT NULL UNIQUE
);

CREATE TABLE statut_candidature (
    id       INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code     VARCHAR(30) NOT NULL UNIQUE,
    libelle  VARCHAR(80) NOT NULL
);

CREATE TABLE resultat (
    id       INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code     VARCHAR(20) NOT NULL UNIQUE,
    libelle  VARCHAR(50) NOT NULL
);

CREATE TABLE type_question (
    id       INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code     VARCHAR(20) NOT NULL UNIQUE,
    libelle  VARCHAR(50) NOT NULL
);

-- Reponse du candidat a la proposition de conditions de travail
CREATE TABLE reponse_condition (
    id       INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code     VARCHAR(20) NOT NULL UNIQUE,
    libelle  VARCHAR(50) NOT NULL
);

CREATE TABLE type_contrat (
    id       INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code     VARCHAR(20) NOT NULL UNIQUE,
    libelle  VARCHAR(80) NOT NULL
);

CREATE TABLE type_notification (
    id       INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    code     VARCHAR(30) NOT NULL UNIQUE,
    libelle  VARCHAR(80) NOT NULL
);

